import type { ReactNode } from 'react';
import { Typography } from 'antd';
import { PAGE_GRADIENTS, usePageGradients } from '@/hooks/usePageStyleVars';

interface Props {
  title: string;
  subtitle?: string;
  icon?: ReactNode;
  avatarText?: string;
  avatarSrc?: string;
  gradient?: keyof typeof PAGE_GRADIENTS;
  extra?: ReactNode;
}

export function PageHero({
  title,
  subtitle,
  icon,
  avatarText,
  avatarSrc,
  gradient = 'blue',
  extra,
}: Props) {
  const gradients = usePageGradients();
  const avatarContent = avatarSrc ? (
    <img
      src={avatarSrc}
      alt=""
      style={{ width: '100%', height: '100%', objectFit: 'cover', display: 'block' }}
    />
  ) : (
    icon ?? avatarText?.slice(0, 1).toUpperCase() ?? '?'
  );

  return (
    <header className="page-hero">
      <div
        className="page-hero__avatar"
        style={avatarSrc ? { background: '#fff', overflow: 'hidden' } : { background: gradients[gradient] ?? PAGE_GRADIENTS[gradient] }}
      >
        {avatarContent}
      </div>
      <div style={{ flex: 1, minWidth: 0 }}>
        <Typography.Title level={2} className="page-hero__title">
          {title}
        </Typography.Title>
        {subtitle && (
          <Typography.Text type="secondary" className="page-hero__subtitle">
            {subtitle}
          </Typography.Text>
        )}
      </div>
      {extra}
    </header>
  );
}
